"use client";

import { keepFormOnSubmit } from "@/lib/use-keep-form";
import Link from "next/link";
import { Suspense, useActionState } from "react";
import { useSearchParams } from "next/navigation";
import { login, register } from "@/app/actions/auth";

function safeNext(n: string | null) {
  return n && n.startsWith("/") && !n.startsWith("//") ? n : "/account";
}

/** Reads ?next= on the client so the form itself can live in the static shell (works before hydration). */
function NextInput() {
  return <input type="hidden" name="next" value={safeNext(useSearchParams().get("next"))} />;
}

function NextLink({ to, children }: { to: string; children: React.ReactNode }) {
  const next = safeNext(useSearchParams().get("next"));
  return <Link href={`${to}?next=${encodeURIComponent(next)}`} className="font-semibold text-maroon hover:underline">{children}</Link>;
}

function FieldError({ errors }: { errors?: string[] }) {
  return errors?.length ? <p className="mt-1 text-xs text-danger">{errors[0]}</p> : null;
}

export function LoginForm() {
  const [state, action, pending] = useActionState(login, undefined);
  return (
    <form action={action} onSubmit={keepFormOnSubmit(action)} className="space-y-4">
      <Suspense fallback={<input type="hidden" name="next" value="/account" />}><NextInput /></Suspense>
      <div>
        <label className="label" htmlFor="email">Email</label>
        <input id="email" name="email" type="email" autoComplete="email" required className="input" />
        <FieldError errors={state?.fieldErrors?.email} />
      </div>
      <div>
        <div className="flex items-baseline justify-between">
          <label className="label" htmlFor="password">Password</label>
          <Link href="/forgot-password" className="text-xs text-maroon hover:underline">Forgot password?</Link>
        </div>
        <input id="password" name="password" type="password" autoComplete="current-password" required className="input" />
        <FieldError errors={state?.fieldErrors?.password} />
      </div>
      {state?.error && <p role="alert" className="rounded-md bg-danger/10 p-3 text-sm text-danger">{state.error}</p>}
      <button disabled={pending} className="btn-brass w-full py-3">{pending ? "Signing in…" : "Sign in"}</button>
      <p className="text-center text-sm">New to Sun Metals Store? <Suspense fallback={<Link href="/register" className="font-semibold text-maroon">Create your account</Link>}><NextLink to="/register">Create your account</NextLink></Suspense></p>
    </form>
  );
}

export function RegisterForm() {
  const [state, action, pending] = useActionState(register, undefined);
  return (
    <form action={action} onSubmit={keepFormOnSubmit(action)} className="space-y-4">
      <Suspense fallback={<input type="hidden" name="next" value="/account" />}><NextInput /></Suspense>
      <div>
        <label className="label" htmlFor="name">Your name</label>
        <input id="name" name="name" autoComplete="name" required className="input" />
        <FieldError errors={state?.fieldErrors?.name} />
      </div>
      <div>
        <label className="label" htmlFor="phone">Mobile number</label>
        <input id="phone" name="phone" type="tel" inputMode="tel" autoComplete="tel" required className="input" placeholder="10-digit mobile" />
        <FieldError errors={state?.fieldErrors?.phone} />
      </div>
      <div>
        <label className="label" htmlFor="email">Email</label>
        <input id="email" name="email" type="email" autoComplete="email" required className="input" />
        <FieldError errors={state?.fieldErrors?.email} />
      </div>
      <div>
        <label className="label" htmlFor="password">Password</label>
        <input id="password" name="password" type="password" autoComplete="new-password" required minLength={8} className="input" placeholder="At least 8 characters, with a number" />
        <FieldError errors={state?.fieldErrors?.password} />
      </div>
      {state?.error && <p role="alert" className="rounded-md bg-danger/10 p-3 text-sm text-danger">{state.error}</p>}
      <button disabled={pending} className="btn-brass w-full py-3">{pending ? "Creating account…" : "Create account"}</button>
      <p className="text-center text-sm">Already have an account? <Suspense fallback={<Link href="/login" className="font-semibold text-maroon">Sign in</Link>}><NextLink to="/login">Sign in</NextLink></Suspense></p>
    </form>
  );
}
